const assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),{createHash}=require('node:crypto'),vscode=require('vscode');
const {Cdp,sleep}=require('./cdp.cjs');
exports.run=async()=>{
 const fixture=await vscode.extensions.getExtension('synthetic.current-plugin-capture').activate(),cdp=await Cdp.connect(Number(process.env.AG_CAPTURE_CDP_PORT)),evidence=process.env.AG_CAPTURE_EVIDENCE,shots=[];
 const until=async(fn,label)=>{for(let i=0;i<200;i++){if(await fn())return;await sleep(40)}throw Error('Timeout: '+label)};
 let ui;const read=e=>cdp.eval(e,ui);assert.equal(vscode.extensions.getExtension('google.google-antigravity'),undefined);
 try{
 await vscode.commands.executeCommand('workbench.action.closeAuxiliaryBar');await vscode.commands.executeCommand('notifications.clearAll');
 await vscode.commands.executeCommand('antigravityAccounts.accounts.focus');ui=await cdp.find('#quota-search');const main=await cdp.find('.monaco-workbench'),native=e=>cdp.eval(e,main);
 const capture=async(file,title,layout)=>{await vscode.commands.executeCommand('notifications.clearAll');await sleep(150);const text=await read('document.body.innerText');assert.doesNotMatch(text,/(?:Bearer |refresh_token|access_token|csrfToken)/i);const emails=text.match(/[^\s<>"'@]+@[^\s<>"'@]+\.[A-Za-z]{2,}/g)||[];assert.ok(emails.every(e=>e.endsWith('@example.test')),JSON.stringify(emails));const r=await cdp.send('Page.captureScreenshot',{format:'png'},main.session);const local=path.join(evidence,file);await fs.writeFile(local,Buffer.from(r.data,'base64'));shots.push({file,title,path:local,language:'zh-CN',actualVsCode:true,syntheticAccounts:true,syntheticQuota:true,layout,privacyTextCheck:true,bytes:Buffer.from(r.data,'base64').length,sha256:createHash('sha256').update(Buffer.from(r.data,'base64')).digest('hex')});console.log('CAPTURED '+file)};
 const resizeSidebar=async width=>{const side=await native('document.querySelector(".part.sidebar").getBoundingClientRect().toJSON()'),before=await read('innerWidth'),sashes=await native('[...document.querySelectorAll(".monaco-sash.vertical")].map(n=>n.getBoundingClientRect().toJSON()).filter(b=>b.width&&b.height)'),sash=sashes.sort((a,b)=>Math.abs(a.x+a.width/2-side.right)-Math.abs(b.x+b.width/2-side.right))[0],x=sash.x+sash.width/2,y=sash.y+sash.height/2;for(const m of [{type:'mouseMoved',x,y},{type:'mousePressed',x,y,button:'left',clickCount:1},{type:'mouseMoved',x:x+width-before,y,button:'left',buttons:1},{type:'mouseReleased',x:x+width-before,y,button:'left',clickCount:1}])await cdp.send('Input.dispatchMouseEvent',m,main.session);await sleep(150)};
 await until(()=>read('document.querySelectorAll(".account").length===4'),'quota cards');await resizeSidebar(440);
 await read('document.querySelector("#quota-compare").selectedIndex=2;document.querySelector("#quota-compare").dispatchEvent(new Event("change"))');
 await cdp.click(ui,'.account details[data-key="Gemini"] summary');await read('document.querySelector("#quota-overview").scrollIntoView({block:"start"})');await capture('01-quota-overview-zh.png','额度总览（虚构测试账号／模拟额度）',{width:await read('innerWidth')});
 await resizeSidebar(240);await read('window.scrollTo(0,0)');const narrow=await read('({width:innerWidth,client:document.documentElement.clientWidth,scroll:document.documentElement.scrollWidth})');assert.ok(narrow.width>=220&&narrow.width<=243);assert.ok(narrow.scroll<=narrow.client);await capture('02-quota-narrow-zh.png','额度总览窄侧栏（240px，模拟数据）',narrow);
 await vscode.commands.executeCommand('workbench.action.closeSidebar');await vscode.commands.executeCommand('antigravityAccounts.automation.open');ui=await cdp.find('#mode');await until(()=>read('document.querySelector("#account").options.length===4'),'automation account choices');assert.equal((await fixture.automation.store.read()).enabled,false);await capture('03-scheduled-settings-zh.png','定时唤醒设置（默认关闭／未发送请求）',{width:await read('innerWidth')});
 await cdp.click(ui,'#models');await until(()=>read('document.querySelector("#model").value==="synthetic-text-alpha"'),'synthetic catalog');await read('document.querySelector("#timezone").value="Asia/Shanghai";document.querySelector("#times").value="08:00,20:30";document.querySelector("#weekdays").value="1,2,3,4,5"');await cdp.click(ui,'#preview');await until(()=>read('document.querySelector("#preview-result").textContent.includes("Asia/Shanghai")'),'schedule preview');await cdp.click(ui,'#save');await until(async()=> (await fixture.automation.store.read()).tasks.length===1,'paused synthetic task');await read('document.querySelector("#task-form").scrollIntoView({block:"start"})');await capture('04-schedule-task-zh.png','日周历任务与预览（任务暂停／总开关关闭）',{width:await read('innerWidth')});
 await vscode.commands.executeCommand('antigravityAccounts.images.open');ui=await cdp.find('#compareAccounts');await until(()=>read('document.querySelector("#model").value==="synthetic-image-model"'),'image choices');await cdp.click(ui,'#compareAccounts');await until(()=>read('document.querySelectorAll("#recommendations button").length===4'),'model-specific account comparison');await read('document.querySelector(".composer").scrollTop=0;window.scrollTo(0,0)');assert.ok(await read('document.querySelector("#recommendations").textContent.includes("未知")'));await capture('05-image-account-history-zh.png','生图账号额度比较与虚构历史任务',{width:await read('innerWidth')});
 const a=fixture.accounts[0],{accountDisplayFingerprint}=require('../../out/quota-presentation'),now=Date.now();
 for(const [i,fraction]of [.22,.41,null,.78,.996].entries())await fixture.history.history.record({accountId:a.id,fingerprint:accountDisplayFingerprint(a),kind:'bucket',key:'synthetic-chart-series',label:'Gemini Pro · 模拟观察',observedAt:new Date(now-(5-i)*600000).toISOString(),fraction,resetAt:null});
 await vscode.commands.executeCommand('antigravityAccounts.quota.history');ui=await cdp.find('#chart');await until(()=>read('document.querySelectorAll("#rows tr").length===9'),'quota history');await read('document.querySelector("#kind-filter").value="bucket";document.querySelector("#kind-filter").dispatchEvent(new Event("change"))');await read('document.querySelector("#account-filter").value="'+a.id+'";document.querySelector("#account-filter").dispatchEvent(new Event("change"))');await until(()=>read('document.querySelectorAll("#rows tr").length===5'),'history filter');await capture('06-quota-history-zh.png','额度观察历史（模拟观察，未知值单列）',{width:await read('innerWidth')});
 assert.equal((await fixture.automation.store.read()).enabled,false);assert.equal((await fixture.automation.store.read()).consent,false);assert.equal(fixture.wakeCalls(),0);assert.equal(fixture.imageRuns(),0);
 await fs.writeFile(path.join(evidence,'capture-receipt.json'),JSON.stringify({passed:true,sourceCommit:process.env.AG_CAPTURE_COMMIT,vscode:vscode.version,shots,productionUi:true,syntheticAccounts:true,syntheticQuota:true,realCredentials:false,googleRequests:false,officialAccountSwitches:false,scheduledMasterEnabled:false,wakeModelRequests:0,imageModelRequests:0,simulatedImageQuotaReads:fixture.reads()},null,2));
 }finally{fixture.automation.engine.dispose();cdp.close()}
};

